class Registry:
 def __init__(self,rows):
  self.by_id={row[0]:row for row in rows}
  self.by_alias={}
  for row in rows:
   alias=row[1]
   if alias in self.by_alias:
    prev=self.by_alias[alias]
    ids=sorted((prev[0],row[0]))
    raise AliasCollision(f"alias {alias!r} collides between ids {ids[0]} and {ids[1]}")
   self.by_alias[alias]=row
 def by_exact_id(self,item_id): return self.by_id[item_id]
 def by_name(self,alias): return self.by_alias[alias]

